    private void send(BankBook.Action action,UUID source,UUID destination,UUID peer,long value,long goal,String text,int kind){if(pending!=null)return;pending=UUID.randomUUID();this.action=action;sent=net.minecraft.Util.getMillis();long revision=confirmation==null?state.getLong("Revision"):confirmRevision;PacketDistributor.sendToServer(new BankRequest(pending,revision,action,source,destination,peer,value,goal,text,kind,false));}
    @Override public void tick(){if(!SocialHubScreen.unobstructed(this))return;long now=net.minecraft.Util.getMillis();if(pending!=null&&now-sent>8000){pending=null;result="timeout";updated=now;}if(pending==null&&confirmation==null&&form==0&&now-updated>4000)send(BankBook.Action.VIEW,null,null,null,0,0,"",0);}
    private long value(){try{return Long.parseLong(amount.getValue());}catch(NumberFormatException e){return -1;}}
    private void select(int next){tab=next;form=0;confirmation=null;transition();focus(null);}
    private void focus(EditBox input){for(var f:List.of(name,amount,note))f.setFocused(f==input);setFocused(input);}
    private CompoundTag account(UUID id){for(Tag raw:state.getList("Accounts",10)){var t=(CompoundTag)raw;if(t.getUUID("Id").equals(id))return t;}return null;}
    private Component accountName(UUID id){var a=id==null?null:account(id);return a==null?tr("primary"):Component.literal(a.getString("Name"));}
    private void sourceNext(){var ids=new ArrayList<UUID>();ids.add(null);for(Tag raw:state.getList("Accounts",10))ids.add(((CompoundTag)raw).getUUID("Id"));source=ids.get((ids.indexOf(source)+1)%ids.size());}
    private void confirm(Component title,Runnable task){confirmRevision=state.getLong("Revision");confirmTitle=title;confirmation=task;focus(null);}
    private void confirmTransfer(){long value=value();if(value<=0){result="invalid";return;}UUID recipient=peer;String memo=note.getValue();boolean invoice=requesting;confirm(tr(invoice?"confirm_request":"confirm_transfer",peerName,BankClient.money(value),accountName(source)),()->send(invoice?BankBook.Action.REQUEST:BankBook.Action.TRANSFER,source,null,recipient,value,0,memo.isBlank()&&invoice?tr("payment_note").getString():memo,0));}
    private void resolve(){if(value()<=0){result="invalid";return;}UUID id=null;try{id=UUID.fromString(name.getValue());}catch(IllegalArgumentException ignored){}send(BankBook.Action.RESOLVE,null,null,id,0,0,name.getValue().strip(),0);}
