    private void labelField(GuiGraphics g,EditBox field,Component label,int y,float partial){text(g,label,28,y,550,MUTED);field.setX(28);field.setY(y+16);field.setVisible(true);field.setEditable(pending==null&&confirmation==null);field.render(g,(int)mx,(int)my,partial);}
    @Override public boolean mouseClicked(double x,double y,int button){if(confirmation!=null){super.mouseClicked(x,y,button);return true;}if(body().contains(layout.localX(x),layout.localY(y)))for(var f:List.of(name,amount,note))if(f.isVisible()&&f.mouseClicked(layout.localX(x),layout.localY(y),button)){focus(f);return true;}focus(null);return super.mouseClicked(x,y,button);}
    @Override public boolean keyPressed(int key,int scan,int mods){if(confirmation!=null){if(key==256)confirmation=null;return true;}for(var f:List.of(name,amount,note))if(f.isVisible()&&f.isFocused()&&key!=256&&f.keyPressed(key,scan,mods))return true;return super.keyPressed(key,scan,mods);}
    @Override public boolean charTyped(char c,int mods){if(confirmation!=null)return false;for(var f:List.of(name,amount,note))if(f.isVisible()&&f.isFocused()&&f.charTyped(c,mods))return true;return false;}
    @Override public boolean mouseScrolled(double x,double y,double dx,double dy){return confirmation!=null||super.mouseScrolled(x,y,dx,dy);}
